"""Import actual Vampir8 nControl profiles; committed output builds without nControl."""
from pathlib import Path
import argparse,runpy,json
root=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--source',required=True,help='Path to your local polish_signals.py');a=p.parse_args()
d=runpy.run_path(a.source);templates=[];rows=[];messages=[]
quote=lambda s:json.dumps(s,ensure_ascii=False)
for profile in d['PROFILES']:
    _,head,name,colors,roles=profile;states=[];codes=d['available'](profile);patterns=[]
    for aspect in codes:
        pixels=[];lamps=d['lamps'](profile,aspect);patterns.append('{'+','.join(str({'off':0,'on':1,'blink':2}[v]) for v in lamps)+'}')
        for color,effect in zip(colors,lamps):
            rgb=d['COLORS'][color].lstrip('#')
            pixels.append({'effect':{'on':'solid','off':'off','blink':'blink'}[effect],'color':[int(rgb[i:i+2],16) for i in (0,2,4)]+[0]})
        states.append({'value':aspect,'pixels':pixels})
        messages.append({'schema':'ncontrol-signal-v1','label':'Signal1','head':head,'aspect':aspect,'colors':list(colors),'roles':list(roles),'lamps':lamps,'blink_period_ms':1000,'mode':'operational'})
    name={'shunt':'Shunting signal','classic-RG':'Traffic light (MQTT)'}.get(head,str(len(colors))+'-lamp signal: '+'-'.join({'green':'G','red':'R','yellow':'Y','white':'W','blue':'B'}[c] for c in colors))
    templates.append({'id':'nc-'+head,'name':name,'kind':'signal','head':head,'count':len(colors),'colors':list(colors),'roles':list(roles),'states':states})
    rows.append('{'+','.join([quote(head),str(len(colors)),'{'+','.join(map(quote,colors))+'}','{'+','.join(map(quote,roles))+'}',str(len(codes)),'{'+','.join(map(quote,codes))+'}','{'+','.join(patterns)+'}'])+'}')
(root/'web-editor/src/signals.generated.json').write_text(json.dumps(templates,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
header='#pragma once\n// Generated by tools/import_signals.py from actual nControl definitions.\nnamespace hub {\nstruct SignalProfile {const char* head;int count;const char* colors[5];const char* roles[5];int aspectCount;const char* aspects[12];uint8_t lamps[12][5];};\ninline const SignalProfile SignalProfiles[]={\n'+',\n'.join(rows)+'\n};\ninline const SignalProfile* signalProfile(const std::string& head){for(const auto& p:SignalProfiles)if(head==p.head)return &p;return nullptr;}\n}\n'
(root/'include/signal_profiles.h').write_text(header,encoding='utf-8')
(root/'examples/ncontrol-signals.json').write_text(json.dumps(messages,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Imported',len(templates),'native nControl profiles')
